"explanation": "<ruby>答<rt>こた</rt></ruby>えは <span class=\"frac\"><span class=\"n\">5</span><span class=\"d\">2</span></span> です。2<span class=\"frac\"><span class=\"n\">1</span><span class=\"d\">2</span></span> と<ruby>書<rt>か</rt></ruby>いても<ruby>同<rt>おな</rt></ruby>じ<ruby>大<rt>おお</rt></ruby>きさです。\n<ruby>分母<rt>ぶんぼ</rt></ruby>はそのままで<ruby>分子<rt>ぶんし</rt></ruby>に 4 をかけると <span class=\"frac\"><span class=\"n\">20</span><span class=\"d\">8</span></span> になります。\n<ruby>分子<rt>ぶんし</rt></ruby>と<ruby>分母<rt>ぶんぼ</rt></ruby>を 4 でわって<ruby>約分<rt>やくぶん</rt></ruby>すると <span class=\"frac\"><span class=\"n\">5</span><span class=\"d\">2</span></span> です。\n<ruby>分母<rt>ぶんぼ</rt></ruby>にも 4 をかけると <span class=\"frac\"><span class=\"n\">20</span><span class=\"d\">32</span></span> となり、もとの <span class=\"frac\"><span class=\"n\">5</span><span class=\"d\">8</span></span> と<ruby>同<rt>おな</rt></ruby>じ<ruby>大<rt>おお</rt></ruby>きさにしかならないので<ruby>注意<rt>ちゅうい</rt></ruby>しましょう。\nポイント: かけたあとに<ruby>約分<rt>やくぶん</rt></ruby>できないか<ruby>必<rt>かなら</rt></ruby>ず<ruby>見<rt>み</rt></ruby>ます。"
