"explanation": "<ruby>答<rt>こた</rt></ruby>えは「<ruby>分子<rt>ぶんし</rt></ruby>どうし、<ruby>分母<rt>ぶんぼ</rt></ruby>どうしをかける」です。\n<span class=\"frac\"><span class=\"n\">2</span><span class=\"d\">5</span></span> × <span class=\"frac\"><span class=\"n\">3</span><span class=\"d\">7</span></span> は、<ruby>分子<rt>ぶんし</rt></ruby>が 2 × 3 = 6、<ruby>分母<rt>ぶんぼ</rt></ruby>が 5 × 7 = 35 となり <span class=\"frac\"><span class=\"n\">6</span><span class=\"d\">35</span></span> になります。\nたし<ruby>算<rt>ざん</rt></ruby>のときは<ruby>分母<rt>ぶんぼ</rt></ruby>をそろえてから<ruby>分子<rt>ぶんし</rt></ruby>だけをたしますが、かけ<ruby>算<rt>ざん</rt></ruby>では<ruby>分母<rt>ぶんぼ</rt></ruby>をそろえる<ruby>必要<rt>ひつよう</rt></ruby>はありません。\nやり<ruby>方<rt>かた</rt></ruby>が<ruby>別<rt>べつ</rt></ruby>なので<ruby>混<rt>ま</rt></ruby>ぜないようにします。\nポイント: かけ<ruby>算<rt>ざん</rt></ruby>は<ruby>上<rt>うえ</rt></ruby>と<ruby>上<rt>うえ</rt></ruby>、<ruby>下<rt>した</rt></ruby>と<ruby>下<rt>した</rt></ruby>をかけます。"
