"explanation": "<ruby>答<rt>こた</rt></ruby>えは <span class=\"frac\"><span class=\"n\">3</span><span class=\"d\">4</span></span> です。\n<ruby>分子<rt>ぶんし</rt></ruby>は 5 × 9 = 45、<ruby>分母<rt>ぶんぼ</rt></ruby>は 6 × 10 = 60 なので <span class=\"frac\"><span class=\"n\">45</span><span class=\"d\">60</span></span> になります。\n<ruby>分子<rt>ぶんし</rt></ruby>と<ruby>分母<rt>ぶんぼ</rt></ruby>を 15 でわると <span class=\"frac\"><span class=\"n\">3</span><span class=\"d\">4</span></span> です。\nかける<ruby>前<rt>まえ</rt></ruby>に 5 と 10、9 と 6 を<ruby>先<rt>さき</rt></ruby>に<ruby>約分<rt>やくぶん</rt></ruby>しても<ruby>同<rt>おな</rt></ruby>じ<ruby>答<rt>こた</rt></ruby>えになり、<ruby>数<rt>かず</rt></ruby>が<ruby>小<rt>ちい</rt></ruby>さくなって<ruby>計算<rt>けいさん</rt></ruby>がらくになります。\n<ruby>分子<rt>ぶんし</rt></ruby>どうし<ruby>分母<rt>ぶんぼ</rt></ruby>どうしをたすと <span class=\"frac\"><span class=\"n\">14</span><span class=\"d\">16</span></span>、つまり <span class=\"frac\"><span class=\"n\">7</span><span class=\"d\">8</span></span> になってしまうので<ruby>気<rt>き</rt></ruby>をつけましょう。\nポイント: かける<ruby>前<rt>まえ</rt></ruby>の<ruby>約分<rt>やくぶん</rt></ruby>が<ruby>近道<rt>ちかみち</rt></ruby>です。"
