"explanation": "<ruby>答<rt>こた</rt></ruby>えは <span class=\"frac\"><span class=\"n\">1</span><span class=\"d\">2</span></span> m<sup>2</sup> です。\n<ruby>長方形<rt>ちょうほうけい</rt></ruby>の<ruby>面積<rt>めんせき</rt></ruby>は<ruby>縦<rt>たて</rt></ruby>×<ruby>横<rt>よこ</rt></ruby>なので、<span class=\"frac\"><span class=\"n\">4</span><span class=\"d\">5</span></span> × <span class=\"frac\"><span class=\"n\">5</span><span class=\"d\">8</span></span> を<ruby>計算<rt>けいさん</rt></ruby>します。\n<ruby>分子<rt>ぶんし</rt></ruby>は 4 × 5 = 20、<ruby>分母<rt>ぶんぼ</rt></ruby>は 5 × 8 = 40 なので <span class=\"frac\"><span class=\"n\">20</span><span class=\"d\">40</span></span>、<ruby>約分<rt>やくぶん</rt></ruby>して <span class=\"frac\"><span class=\"n\">1</span><span class=\"d\">2</span></span> m<sup>2</sup> です。\n<ruby>辺<rt>へん</rt></ruby>の<ruby>長<rt>なが</rt></ruby>さをたしても<ruby>面積<rt>めんせき</rt></ruby>にはなりません。1 m より<ruby>短<rt>みじか</rt></ruby>い<ruby>辺<rt>へん</rt></ruby>どうしなので、<ruby>答<rt>こた</rt></ruby>えが 1 をこえたら<ruby>見直<rt>みなお</rt></ruby>しましょう。\nポイント: <ruby>辺<rt>へん</rt></ruby>が<ruby>分数<rt>ぶんすう</rt></ruby>でも<ruby>面積<rt>めんせき</rt></ruby>は<ruby>縦<rt>たて</rt></ruby>×<ruby>横<rt>よこ</rt></ruby>です。"
