"question": "もとの<ruby>図形<rt>ずけい</rt></ruby>の<ruby>角<rt>かく</rt></ruby>の<ruby>大<rt>おお</rt></ruby>きさは<ruby>変<rt>か</rt></ruby>えずに、<ruby>辺<rt>へん</rt></ruby>の<ruby>長<rt>なが</rt></ruby>さをすべて<span class=\"frac\"><span class=\"n\">1</span><span class=\"d\">2</span></span>にしてかいた<ruby>図形<rt>ずけい</rt></ruby>を<ruby>何<rt>なん</rt></ruby>といいますか。",
