"topic": "縮尺の基本",
"level": 1,
"question": "<ruby>縮尺<rt>しゅくしゃく</rt></ruby>が <span class=\"frac\"><span class=\"n\">1</span><span class=\"d\">10000</span></span> の<ruby>地図<rt>ちず</rt></ruby>があります。この<ruby>地図<rt>ちず</rt></ruby>の<ruby>上<rt>うえ</rt></ruby>で 3cm の<ruby>長<rt>なが</rt></ruby>さは、<ruby>実際<rt>じっさい</rt></ruby>には<ruby>何<rt>なん</rt></ruby>mですか。",
