"question": "<ruby>下<rt>した</rt></ruby>の<ruby>図<rt>ず</rt></ruby>で、<ruby>三角形<rt>さんかくけい</rt></ruby>エオカは<ruby>三角形<rt>さんかくけい</rt></ruby>アイウの<ruby>拡大図<rt>かくだいず</rt></ruby>です。<ruby>辺<rt>へん</rt></ruby>アイが 4cm、<ruby>辺<rt>へん</rt></ruby>イウが 6cm、<ruby>辺<rt>へん</rt></ruby>エオが 10cm のとき、<ruby>辺<rt>へん</rt></ruby>オカの<ruby>長<rt>なが</rt></ruby>さは<ruby>何<rt>なん</rt></ruby>cmですか。",
