"unit": "e6_u04",
"topic": "かげと高さ",
"level": 3,
"question": "<ruby>晴<rt>は</rt></ruby>れた<ruby>日<rt>ひ</rt></ruby>の<ruby>同<rt>おな</rt></ruby>じ<ruby>時刻<rt>じこく</rt></ruby>に、<ruby>高<rt>たか</rt></ruby>さ 1.2m の<ruby>棒<rt>ぼう</rt></ruby>のかげの<ruby>長<rt>なが</rt></ruby>さをはかると 1.5m でした。そのとなりに<ruby>立<rt>た</rt></ruby>つ<ruby>木<rt>き</rt></ruby>のかげの<ruby>長<rt>なが</rt></ruby>さは 6m でした。<ruby>木<rt>き</rt></ruby>の<ruby>高<rt>たか</rt></ruby>さは<ruby>何<rt>なん</rt></ruby>mですか。",
