"question": "<ruby>正七角形<rt>せいしちかくけい</rt></ruby>、<ruby>正五角形<rt>せいごかくけい</rt></ruby>、<ruby>正九角形<rt>せいきゅうかくけい</rt></ruby>、<ruby>正八角形<rt>せいはちかくけい</rt></ruby>のうち、<ruby>点対称<rt>てんたいしょう</rt></ruby>な<ruby>図形<rt>ずけい</rt></ruby>はどれですか。",
