"question": "<ruby>直径<rt>ちょっけい</rt></ruby> 24 cm の<ruby>丸<rt>まる</rt></ruby>いケーキを<ruby>真上<rt>まうえ</rt></ruby>から<ruby>見<rt>み</rt></ruby>ると<ruby>円<rt>えん</rt></ruby>になります。この<ruby>円<rt>えん</rt></ruby>の<ruby>面積<rt>めんせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby> cm<sup>2</sup> ですか。<ruby>円周率<rt>えんしゅうりつ</rt></ruby>は 3.14 とします。",
