"level": 2,
"question": "<ruby>底面<rt>ていめん</rt></ruby>の<ruby>直径<rt>ちょっけい</rt></ruby>が 8 cm、<ruby>高<rt>たか</rt></ruby>さが 15 cm の<ruby>円柱<rt>えんちゅう</rt></ruby>の<ruby>形<rt>かたち</rt></ruby>をした<ruby>水筒<rt>すいとう</rt></ruby>があります。<ruby>内側<rt>うちがわ</rt></ruby>いっぱいに<ruby>水<rt>みず</rt></ruby>を<ruby>入<rt>い</rt></ruby>れると、<ruby>水<rt>みず</rt></ruby>の<ruby>体積<rt>たいせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby> cm<sup>3</sup> ですか。<ruby>円周率<rt>えんしゅうりつ</rt></ruby>は 3.14 とします。",
