"question": "<ruby>地図<rt>ちず</rt></ruby>にかかれた<ruby>土地<rt>とち</rt></ruby>の<ruby>形<rt>かたち</rt></ruby>を、<ruby>上<rt>うえ</rt></ruby>の<ruby>辺<rt>へん</rt></ruby>が<ruby>約<rt>やく</rt></ruby>12 m、<ruby>下<rt>した</rt></ruby>の<ruby>辺<rt>へん</rt></ruby>が<ruby>約<rt>やく</rt></ruby>20 m、<ruby>高<rt>たか</rt></ruby>さが<ruby>約<rt>やく</rt></ruby>10 m の<ruby>台形<rt>だいけい</rt></ruby>とみなします。この<ruby>土地<rt>とち</rt></ruby>のおよその<ruby>面積<rt>めんせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby> m<sup>2</sup> ですか。",
