"unit": "e6_u08",
"topic": "面積と重さ",
"level": 3,
"question": "<ruby>畑<rt>はたけ</rt></ruby>のおよその<ruby>形<rt>かたち</rt></ruby>を、<ruby>底辺<rt>ていへん</rt></ruby>が<ruby>約<rt>やく</rt></ruby>25 m、<ruby>高<rt>たか</rt></ruby>さが<ruby>約<rt>やく</rt></ruby>12 m の<ruby>平行四辺形<rt>へいこうしへんけい</rt></ruby>とみなします。この<ruby>畑<rt>はたけ</rt></ruby>に 1 m<sup>2</sup> あたり 30 g の<ruby>肥料<rt>ひりょう</rt></ruby>をまくとき、<ruby>肥料<rt>ひりょう</rt></ruby>はおよそ<ruby>何<rt>なん</rt></ruby> kg いりますか。",
