"topic": "比例の意味",
"level": 1,
"question": "<ruby>同<rt>おな</rt></ruby>じ<ruby>太<rt>ふと</rt></ruby>さの<ruby>針金<rt>はりがね</rt></ruby>があります。<ruby>長<rt>なが</rt></ruby>さ 2 m の<ruby>重<rt>おも</rt></ruby>さをはかると 50 g でした。この<ruby>針金<rt>はりがね</rt></ruby> 6 m の<ruby>重<rt>おも</rt></ruby>さは<ruby>何<rt>なん</rt></ruby> g ですか。",
