"question": "y は x に<ruby>比例<rt>ひれい</rt></ruby>していて、x = 3 のとき y = 12 です。x と y の<ruby>関係<rt>かんけい</rt></ruby>を<ruby>表<rt>あらわ</rt></ruby>す<ruby>式<rt>しき</rt></ruby>はどれですか。",
