"table": null,
"explanation": "<ruby>答<rt>こた</rt></ruby>えは 400 m です。\nグラフは 0 の<ruby>点<rt>てん</rt></ruby>を<ruby>通<rt>とお</rt></ruby>るまっすぐな<ruby>線<rt>せん</rt></ruby>なので、<ruby>時間<rt>じかん</rt></ruby>と<ruby>道<rt>みち</rt></ruby>のりは<ruby>比例<rt>ひれい</rt></ruby>しています。\n<ruby>横<rt>よこ</rt></ruby>の じくの 5 から<ruby>上<rt>うえ</rt></ruby>にたどり、<ruby>線<rt>せん</rt></ruby>とぶつかった<ruby>点<rt>てん</rt></ruby>を たての じくで<ruby>読<rt>よ</rt></ruby>み<ruby>取<rt>と</rt></ruby>ります。\nその<ruby>値<rt>あたい</rt></ruby>は 400 m です。\n10<ruby>分<rt>ぷん</rt></ruby>で 800 m だから 1<ruby>分<rt>ぷん</rt></ruby>あたり 80 m、80 × 5 = 400 と<ruby>計算<rt>けいさん</rt></ruby>しても<ruby>同<rt>おな</rt></ruby>じです。\nポイント: <ruby>比例<rt>ひれい</rt></ruby>のグラフは 0 の<ruby>点<rt>てん</rt></ruby>を<ruby>通<rt>とお</rt></ruby>る<ruby>直線<rt>ちょくせん</rt></ruby>になります。"
