"question": "<ruby>面積<rt>めんせき</rt></ruby>が 24 cm<sup>2</sup> の<ruby>長方形<rt>ちょうほうけい</rt></ruby>をつくります。たての<ruby>長<rt>なが</rt></ruby>さが 4 cm のとき、<ruby>横<rt>よこ</rt></ruby>の<ruby>長<rt>なが</rt></ruby>さは<ruby>何<rt>なん</rt></ruby> cm ですか。",
