"explanation": "<ruby>答<rt>こた</rt></ruby>えは 2:3 です。\n<ruby>比<rt>ひ</rt></ruby>は、<ruby>前<rt>まえ</rt></ruby>と<ruby>後<rt>うし</rt></ruby>ろを<ruby>同<rt>おな</rt></ruby>じ<ruby>数<rt>かず</rt></ruby>でわっても<ruby>等<rt>ひと</rt></ruby>しくなります。\n12 と 18 の<ruby>最大公約数<rt>さいだいこうやくすう</rt></ruby>は 6 なので、12÷6=2、18÷6=3 となり 2:3 です。\n4:6 や 6:9 も 12:18 と<ruby>等<rt>ひと</rt></ruby>しい<ruby>比<rt>ひ</rt></ruby>ですが、まだ<ruby>両方<rt>りょうほう</rt></ruby>を 2 や 3 でわることができるので、いちばん<ruby>小<rt>ちい</rt></ruby>さい<ruby>整数<rt>せいすう</rt></ruby>の<ruby>比<rt>ひ</rt></ruby>ではありません。<ruby>前<rt>まえ</rt></ruby>と<ruby>後<rt>うし</rt></ruby>ろを<ruby>入<rt>い</rt></ruby>れかえないことも<ruby>大切<rt>たいせつ</rt></ruby>です。\nポイント: <ruby>比<rt>ひ</rt></ruby>を<ruby>簡単<rt>かんたん</rt></ruby>にするときは、<ruby>両方<rt>りょうほう</rt></ruby>を<ruby>最大公約数<rt>さいだいこうやくすう</rt></ruby>でわります。"
