"question": "<ruby>下<rt>した</rt></ruby>の<ruby>柱状<rt>ちゅうじょう</rt></ruby>グラフは、ある<ruby>店<rt>みせ</rt></ruby>での1<ruby>回<rt>かい</rt></ruby>の<ruby>買<rt>か</rt></ruby>い<ruby>物<rt>もの</rt></ruby>の<ruby>金額<rt>きんがく</rt></ruby>を 20 <ruby>回<rt>かい</rt></ruby><ruby>分<rt>ぶん</rt></ruby><ruby>調<rt>しら</rt></ruby>べたものです。2000<ruby>円<rt>えん</rt></ruby><ruby>以上<rt>いじょう</rt></ruby>3000<ruby>円<rt>えん</rt></ruby><ruby>未満<rt>みまん</rt></ruby>の<ruby>買<rt>か</rt></ruby>い<ruby>物<rt>もの</rt></ruby>は、<ruby>全体<rt>ぜんたい</rt></ruby>の<ruby>何<rt>なん</rt></ruby>%ですか。",
