"explanation": "<ruby>答<rt>こた</rt></ruby>えは 20 kg <ruby>以上<rt>いじょう</rt></ruby>25 kg <ruby>未満<rt>みまん</rt></ruby> です。\n「15 kg <ruby>以上<rt>いじょう</rt></ruby>20 kg <ruby>未満<rt>みまん</rt></ruby>」は、15 kg はふくみますが 20 kg はふくみません。\n「20 kg <ruby>以上<rt>いじょう</rt></ruby>25 kg <ruby>未満<rt>みまん</rt></ruby>」は 20 kg をふくみます。\nだから、ちょうど 20 kg の<ruby>荷物<rt>にもつ</rt></ruby>は<ruby>後<rt>あと</rt></ruby>の<ruby>階級<rt>かいきゅう</rt></ruby>に<ruby>入<rt>はい</rt></ruby>ります。\n<ruby>境目<rt>さかいめ</rt></ruby>の<ruby>値<rt>あたい</rt></ruby>はどちらにも<ruby>入<rt>はい</rt></ruby>りそうに<ruby>見<rt>み</rt></ruby>えますが、<ruby>以上<rt>いじょう</rt></ruby>と<ruby>未満<rt>みまん</rt></ruby>で<ruby>区切<rt>くぎ</rt></ruby>ることで、どのデータもかならず1つの<ruby>階級<rt>かいきゅう</rt></ruby>だけに<ruby>入<rt>はい</rt></ruby>るようになっています。\nポイント: <ruby>境目<rt>さかいめ</rt></ruby>の<ruby>値<rt>あたい</rt></ruby>は、「<ruby>以上<rt>いじょう</rt></ruby>」と<ruby>書<rt>か</rt></ruby>かれた<ruby>方<rt>ほう</rt></ruby>の<ruby>階級<rt>かいきゅう</rt></ruby>に<ruby>入<rt>はい</rt></ruby>ります。"
