"question": "ある<ruby>作業<rt>さぎょう</rt></ruby>にかかった<ruby>時間<rt>じかん</rt></ruby>を<ruby>調<rt>しら</rt></ruby>べたところ、10<ruby>人<rt>にん</rt></ruby>の<ruby>平均<rt>へいきん</rt></ruby>は 42<ruby>分<rt>ふん</rt></ruby>でした。あとから、もう<ruby>一人<rt>ひとり</rt></ruby>の<ruby>記録<rt>きろく</rt></ruby> 64<ruby>分<rt>ぷん</rt></ruby>を<ruby>加<rt>くわ</rt></ruby>えると、11<ruby>人<rt>にん</rt></ruby><ruby>分<rt>ぶん</rt></ruby>の<ruby>平均<rt>へいきん</rt></ruby>は<ruby>何<rt>なん</rt></ruby><ruby>分<rt>ぷん</rt></ruby>になりますか。",
